<div class="section-heading"><h1><?=e(t('Categories'))?></h1></div><div class="category-grid"><?php foreach ($categories as $c): ?><a class="panel category-card" href="/?category=<?=$c['id']?>"><span class="category-icon"><?=icon('grid')?></span><div><h2><?=e($c['name'])?></h2><p><?=$c['total']?> <?=language()==='zh-CN'?'篇文章':($c['total']==1?'post':'posts')?></p></div><?=icon('arrow')?></a><?php endforeach; ?></div><?php if (!$categories): ?><div class="panel empty"><h2><?=e(t('No categories yet'))?></h2></div><?php endif; ?>
